-- Projects shown on /projects, managed from the admin "Projects" tab.
-- Run once in the Supabase SQL editor. Images live on Cloudinary (folder "projects"); gallery images are watermarked on upload.

create table if not exists public.projects (
  id text primary key,                       -- URL slug, e.g. executive-offices
  title text not null,
  place text not null default '',
  sector text not null default '',
  scope text not null default '',
  summary text not null default '',
  challenge text not null default '',
  solution text not null default '',
  cover_url text,                            -- thumbnail, no watermark
  cover_public_id text,
  images jsonb not null default '[]'::jsonb, -- [{ "url": "...", "publicId": "..." }], watermarked
  sort integer not null default 0,
  created_at timestamptz not null default now()
);

alter table public.projects enable row level security;

drop policy if exists "projects are public" on public.projects;
create policy "projects are public" on public.projects for select using (true);

drop policy if exists "admins manage projects" on public.projects;
create policy "admins manage projects" on public.projects for all
  using (public.is_admin()) with check (public.is_admin());

-- The six projects already on the site.
insert into public.projects (id, title, place, sector, scope, summary, challenge, solution, cover_url, cover_public_id, images, sort) values
  ('executive-offices', 'Executive offices & cabins', 'Lahore', 'Corporate office', 'Executive desks, storage walls & lounge seating', 'Executive cabins with L-shaped desks, full-height storage walls, high-back chairs and lounge seating for visitors.', 'Each cabin had a different size and layout, and the client wanted desks and wall storage that looked built-in rather than off the shelf.', 'We measured every room, manufactured desks, side returns and storage walls to fit, and finished them in matching wood tones with executive chairs and sofas.', 'https://res.cloudinary.com/aepcimps/image/upload/v1794410026/projects/covers/wmzbe7wvj2esvh3jajey.jpg', 'projects/covers/wmzbe7wvj2esvh3jajey', '[{"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410025/projects/is7vjkn4evpvthc7rhuw.jpg", "publicId": "projects/is7vjkn4evpvthc7rhuw"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410027/projects/pevb0uzozj9zpnmyiagk.jpg", "publicId": "projects/pevb0uzozj9zpnmyiagk"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410029/projects/eaoizqrwr3ytwkfnvktl.jpg", "publicId": "projects/eaoizqrwr3ytwkfnvktl"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410036/projects/hmekmql4tbocpvtdqdpt.jpg", "publicId": "projects/hmekmql4tbocpvtdqdpt"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410090/projects/kof4rddm9bblcnhqtu6d.jpg", "publicId": "projects/kof4rddm9bblcnhqtu6d"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410030/projects/vgvmsycoyzurnqyauyuz.jpg", "publicId": "projects/vgvmsycoyzurnqyauyuz"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410045/projects/ftqyj7kkvtieu9mykxow.jpg", "publicId": "projects/ftqyj7kkvtieu9mykxow"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410055/projects/b9z6dosik3ic0o9mluyb.jpg", "publicId": "projects/b9z6dosik3ic0o9mluyb"}]'::jsonb, 1),
  ('corporate-open-plan-floor', 'Corporate open-plan floor', 'Lahore', 'Corporate office', 'Linear workstations & task chairs', 'Large open-plan floors furnished with long runs of linear workstations, privacy panels and ergonomic task chairs.', 'Hundreds of seats had to fit around columns and walkways while keeping clear aisles and cable management for every desk.', 'We planned the floor in long bench rows, built workstations with panel screens and wire trays, and installed them row by row.', 'https://res.cloudinary.com/aepcimps/image/upload/v1794410093/projects/covers/qlnjv0knfkeqv5kaloy2.jpg', 'projects/covers/qlnjv0knfkeqv5kaloy2', '[{"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410091/projects/rpx8xcoxakvimtnpptuu.jpg", "publicId": "projects/rpx8xcoxakvimtnpptuu"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410094/projects/n0tbyddwnft1ef8wlg8g.jpg", "publicId": "projects/n0tbyddwnft1ef8wlg8g"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410089/projects/k54g2fkc4mlihtlodgez.jpg", "publicId": "projects/k54g2fkc4mlihtlodgez"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410044/projects/tutlh0qfytxtqmd3jerk.jpg", "publicId": "projects/tutlh0qfytxtqmd3jerk"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410048/projects/widld7a9kgdxpcopjhnl.jpg", "publicId": "projects/widld7a9kgdxpcopjhnl"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410037/projects/assyefcdwnebix0ujwef.jpg", "publicId": "projects/assyefcdwnebix0ujwef"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410031/projects/ylcelo3gwc3duxq1znks.jpg", "publicId": "projects/ylcelo3gwc3duxq1znks"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410039/projects/ys4odbozzqikk4jy5luo.jpg", "publicId": "projects/ys4odbozzqikk4jy5luo"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410047/projects/ea9zharxtku0uyd2lttz.jpg", "publicId": "projects/ea9zharxtku0uyd2lttz"}]'::jsonb, 2),
  ('blue-panel-workstations', 'Team workstations', 'Lahore', 'Corporate office', 'Cluster desks with fabric screens', 'Cluster workstations with blue fabric privacy screens, metal frames and mesh chairs for growing teams.', 'The team needed focused desks with some privacy, without closing off the open, collaborative feel of the office.', 'Pinnable fabric screens between facing desks, sturdy powder-coated frames and matching mesh chairs for every seat.', 'https://res.cloudinary.com/aepcimps/image/upload/v1794410084/projects/covers/fkrmna0de3gdlyrcnfvq.jpg', 'projects/covers/fkrmna0de3gdlyrcnfvq', '[{"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410082/projects/yg3qmt9apysfse1csjgh.jpg", "publicId": "projects/yg3qmt9apysfse1csjgh"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410085/projects/fyr91mygfszh52yepkcm.jpg", "publicId": "projects/fyr91mygfszh52yepkcm"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410058/projects/uo5bgs2oludovy9wjzvb.jpg", "publicId": "projects/uo5bgs2oludovy9wjzvb"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410059/projects/c9pw28ofxqvilvjtap5s.jpg", "publicId": "projects/c9pw28ofxqvilvjtap5s"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410049/projects/pdel4x01rhcpffjixhrp.jpg", "publicId": "projects/pdel4x01rhcpffjixhrp"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410066/projects/fo1qc5cz8sh2z24l4oym.jpg", "publicId": "projects/fo1qc5cz8sh2z24l4oym"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410069/projects/stwtypbbejefltxwley3.jpg", "publicId": "projects/stwtypbbejefltxwley3"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410081/projects/qaolgmkpvpezrqqdnuto.jpg", "publicId": "projects/qaolgmkpvpezrqqdnuto"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410046/projects/pyzopx0uixldw2uwwg7p.jpg", "publicId": "projects/pyzopx0uixldw2uwwg7p"}]'::jsonb, 3),
  ('software-house-fit-out', 'Software house fit-out', 'Lahore', 'Technology', 'Developer desks & breakout tables', 'Developer workstations, team tables and storage for a software house working long hours.', 'Developers needed wide desks for multiple screens and comfortable chairs for long shifts, delivered while the office was still being finished.', 'We manufactured wide workstations with cable access, delivered in phases alongside the interior work and installed the final rows on site.', 'https://res.cloudinary.com/aepcimps/image/upload/v1794410071/projects/covers/yhi6etbzihdryatzjxvh.jpg', 'projects/covers/yhi6etbzihdryatzjxvh', '[{"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410070/projects/s5fjfy7rwvwymdpg2jlr.jpg", "publicId": "projects/s5fjfy7rwvwymdpg2jlr"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410072/projects/nrbllg6sldmfrqzydmvs.jpg", "publicId": "projects/nrbllg6sldmfrqzydmvs"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410077/projects/kfqtlda5wyhjmsw04m45.jpg", "publicId": "projects/kfqtlda5wyhjmsw04m45"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410078/projects/llxgmiq0bjiarr9drvwc.jpg", "publicId": "projects/llxgmiq0bjiarr9drvwc"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410079/projects/wsdvcdtkg4qepk5kbbwl.jpg", "publicId": "projects/wsdvcdtkg4qepk5kbbwl"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410051/projects/qs5lryuu5e6ddf3lfdab.jpg", "publicId": "projects/qs5lryuu5e6ddf3lfdab"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410067/projects/gbxjysozlm7abloqeuxi.jpg", "publicId": "projects/gbxjysozlm7abloqeuxi"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410087/projects/n8vydsphdd4nc4kubpxy.jpg", "publicId": "projects/n8vydsphdd4nc4kubpxy"}]'::jsonb, 4),
  ('meeting-rooms-storage', 'Meeting rooms & storage', 'Lahore', 'Corporate office', 'Conference tables, desks & cabinets', 'Conference tables, meeting desks and built-in storage made to the size of each room.', 'Meeting rooms of different shapes needed tables that seat the right number of people with power and cable access in the middle.', 'Oval and rectangular conference tables with built-in cable boxes, plus storage units and cabinets finished to match.', 'https://res.cloudinary.com/aepcimps/image/upload/v1794410041/projects/covers/wf3z6bqyawpxbmqvosri.jpg', 'projects/covers/wf3z6bqyawpxbmqvosri', '[{"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410040/projects/bu3b2bp5dvhu80rdojrd.jpg", "publicId": "projects/bu3b2bp5dvhu80rdojrd"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410065/projects/jokgrxbn3juwu2uxwizc.jpg", "publicId": "projects/jokgrxbn3juwu2uxwizc"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410035/projects/j1upfvwawnsouurod2iu.jpg", "publicId": "projects/j1upfvwawnsouurod2iu"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410042/projects/fmlyom9zsrqba5mpvhmm.jpg", "publicId": "projects/fmlyom9zsrqba5mpvhmm"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410057/projects/zk1pqrbqytk3sdspkfll.jpg", "publicId": "projects/zk1pqrbqytk3sdspkfll"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410060/projects/exxeowr9drginjykrttt.jpg", "publicId": "projects/exxeowr9drginjykrttt"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410062/projects/vxxzwgxdmi637r1rdudo.jpg", "publicId": "projects/vxxzwgxdmi637r1rdudo"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410063/projects/isveeddde7e1ggcmykqr.jpg", "publicId": "projects/isveeddde7e1ggcmykqr"}]'::jsonb, 5),
  ('auditorium-training-hall', 'Auditorium & training hall', 'Lahore', 'Education & training', 'Auditorium seating, training chairs & reception', 'Fixed auditorium seating, training-room chairs, bar stools and a reception counter.', 'The hall needed seating that is comfortable for long sessions, durable for daily use and arranged for clear sight lines.', 'Upholstered auditorium chairs with writing pads, stackable training chairs and a custom reception counter for the entrance.', 'https://res.cloudinary.com/aepcimps/image/upload/v1794410034/projects/covers/u3vvpv12zrydem9soip2.jpg', 'projects/covers/u3vvpv12zrydem9soip2', '[{"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410033/projects/vgtjj6pvgryd6wkwnany.jpg", "publicId": "projects/vgtjj6pvgryd6wkwnany"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410054/projects/wc9d1bcfxpjcepneyytj.jpg", "publicId": "projects/wc9d1bcfxpjcepneyytj"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410053/projects/k0fxkkgnq3ko2gudrnp9.jpg", "publicId": "projects/k0fxkkgnq3ko2gudrnp9"}, {"url": "https://res.cloudinary.com/aepcimps/image/upload/v1794410088/projects/gneliefdut5qt4cpaezj.jpg", "publicId": "projects/gneliefdut5qt4cpaezj"}]'::jsonb, 6)
